/**
 * LAWVOX Frontend API Service Client
 * Connects Next.js Frontend to Express SQLite Backend API at http://localhost:5000/api
 */ const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000/api';
async function fetchJson(endpoint, options) {
    try {
        const res = await fetch(`${API_BASE_URL}${endpoint}`, {
            headers: {
                'Content-Type': 'application/json',
                ...options?.headers || {}
            },
            ...options
        });
        if (!res.ok) {
            console.warn(`[API] Request to ${endpoint} failed with status ${res.status}`);
            return null;
        }
        const json = await res.json();
        return json.success ? json.data : null;
    } catch (error) {
        console.warn(`[API] Error contacting backend at ${API_BASE_URL}${endpoint}:`, error);
        return null;
    }
}
const LawvoxAPI = {
    // 1. Health Check
    async checkHealth () {
        try {
            const res = await fetch(`${API_BASE_URL}/health`);
            const json = await res.json();
            return json.success === true;
        } catch  {
            return false;
        }
    },
    // 2. Dashboard
    async getDashboard () {
        return fetchJson('/dashboard');
    },
    // 3. Cases
    async getCases (params) {
        const query = new URLSearchParams();
        if (params?.category) query.set('category', params.category);
        if (params?.court) query.set('court', params.court);
        if (params?.year) query.set('year', String(params.year));
        const qs = query.toString();
        return fetchJson(`/cases${qs ? `?${qs}` : ''}`);
    },
    async getCaseById (id) {
        return fetchJson(`/cases/${id}`);
    },
    async searchCases (q, filters) {
        const query = new URLSearchParams();
        if (q) query.set('q', q);
        if (filters?.court) query.set('court', filters.court);
        if (filters?.category) query.set('category', filters.category);
        if (filters?.year) query.set('year', String(filters.year));
        return fetchJson(`/search?${query.toString()}`);
    },
    // 4. Bookmarks
    async getBookmarks () {
        return fetchJson('/bookmarks');
    },
    async checkBookmark (caseId) {
        return fetchJson(`/bookmarks/${caseId}`);
    },
    async addBookmark (caseId) {
        return fetchJson(`/bookmarks/${caseId}`, {
            method: 'POST'
        });
    },
    async removeBookmark (caseId) {
        return fetchJson(`/bookmarks/${caseId}`, {
            method: 'DELETE'
        });
    },
    // 5. Listening History
    async getHistory () {
        return fetchJson('/history');
    },
    async recordHistory (data) {
        return fetchJson('/history', {
            method: 'POST',
            body: JSON.stringify(data)
        });
    },
    // 6. Notes
    async getNotes (caseId) {
        const qs = caseId ? `?case_id=${encodeURIComponent(caseId)}` : '';
        return fetchJson(`/notes${qs}`);
    },
    async createNote (data) {
        return fetchJson('/notes', {
            method: 'POST',
            body: JSON.stringify(data)
        });
    },
    async deleteNote (id) {
        return fetchJson(`/notes/${id}`, {
            method: 'DELETE'
        });
    },
    // 7. Profile
    async getProfile () {
        return fetchJson('/profile');
    },
    async updateProfile (data) {
        return fetchJson('/profile', {
            method: 'PUT',
            body: JSON.stringify(data)
        });
    },
    // 8. Settings
    async getSettings () {
        return fetchJson('/settings');
    },
    async updateSettings (data) {
        return fetchJson('/settings', {
            method: 'PUT',
            body: JSON.stringify(data)
        });
    },
    // 9. Recent Searches
    async getRecentSearches () {
        return fetchJson('/searches');
    },
    async addSearch (query) {
        return fetchJson('/searches', {
            method: 'POST',
            body: JSON.stringify({
                query
            })
        });
    }
};
